const supabaseUrl = $env.SUPABASE_URL;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const clinicId = $json.clinic_id;
const phone = $json.patient_phone;

const patientRes = await fetch(`${supabaseUrl}/rest/v1/patients?clinic_id=eq.${clinicId}&phone=eq.${phone}&select=*`, { headers: { 'apikey': key, 'Authorization': `Bearer ${key}` } });
const patients = await patientRes.json();
const patient = patients[0] || { name: null, email: null, status: 'new', total_visits: 0 };

const histRes = await fetch(`${supabaseUrl}/rest/v1/conversations?clinic_id=eq.${clinicId}&patient_phone=eq.${phone}&select=role,content&order=created_at.desc&limit=10`, { headers: { 'apikey': key, 'Authorization': `Bearer ${key}` } });
const history = await histRes.json();

return [{json: { ...$input.first().json, patient, conversation_history: history.reverse(), lead_status: patient.total_visits > 0 ? 'returning' : 'new' }}];

const supabaseUrl = $env.SUPABASE_URL;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const clinicId = $json.clinic_id;
const clinic = $json.clinic;

const availRes = await fetch(`${supabaseUrl}/rest/v1/availability?clinic_id=eq.${clinicId}&active=eq.true&select=day_of_week,slot_start_local&order=day_of_week.asc,slot_start_local.asc`, { headers: { 'apikey': key, 'Authorization': `Bearer ${key}` } });
const slots = await availRes.json();
const days = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const slotsFormatted = slots.map(s => `${days[s.day_of_week]} ${s.slot_start_local}`).join(', ');

const kb = clinic.knowledge_base || {};
const services = (kb.services || []).map(s => `${s.name} (${clinic.currency || 'INR'} ${s.price}, ${s.duration_min}min)`).join(', ');

let prompt = `You are a warm, professional appointment booking assistant for ${clinic.name || ''}, a ${clinic.specialty || ''} clinic.

CLINIC INFORMATION:
- Doctor: ${kb.doctor || ''}
- Address: ${kb.address || ''}
- Hours: ${kb.hours || ''}
- Phone: ${kb.phone || ''}
- Services & Pricing: ${services}
- Available slots: ${slotsFormatted}
- Currency: ${clinic.currency || 'INR'}

PATIENT CONTEXT:
- Patient phone: ${$json.patient_phone}
- Patient status: ${$json.lead_status}
- Patient name: ${$json.patient?.name || 'Unknown'}
- Previous service: ${$json.patient?.last_service || 'N/A'}

YOUR GOALS:
1. Greet patient warmly. If returning, greet by name.
2. Understand appointment need.
3. Recommend a service if unsure.
4. Offer available slots and confirm time.
5. Collect full name and email.
6. Confirm appointment details.
7. Inform confirmation email will be sent.

STRICT RULES:
- NEVER confirm a slot not in the available_slots list.
- NEVER diagnose, prescribe, or give medical advice.
- NEVER share other patient info.
- If emergency keywords detected, respond with emergency services message.
- Keep messages concise (max 3 short paragraphs).
- Use 1-2 emojis max.
- Reply in patient language.
- When confirmed, output: BOOKING_JSON:{"name":"...","email":"...","service":"...","date":"...","time":"..."}`;

return [{json: { ...$json, system_prompt: prompt }}];

const providerName = $json.provider_name;
let aiResponse = '';

if (providerName === 'GROQ' || providerName === 'OPENROUTER') {
  aiResponse = $json.choices?.[0]?.message?.content || '';
} else if (providerName === 'GEMINI') {
  aiResponse = $json.candidates?.[0]?.content?.parts?.[0]?.text || '';
}

// Call fn_increment_ai_quota and fn_mark_provider_success
const supabaseUrl = $env.SUPABASE_URL;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const clinicId = $json.clinic_id;

await fetch(`${supabaseUrl}/rest/v1/rpc/fn_increment_ai_quota`, { method: 'POST', headers: { 'apikey': key, 'Authorization': `Bearer ${key}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ p_clinic_id: clinicId, p_provider_name: providerName }) });
await fetch(`${supabaseUrl}/rest/v1/rpc/fn_mark_provider_success`, { method: 'POST', headers: { 'apikey': key, 'Authorization': `Bearer ${key}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ p_clinic_id: clinicId, p_provider_name: providerName }) });

return [{json: { ...$json, ai_raw_response: aiResponse, provider_used: providerName }}];

let response = $json.ai_raw_response;
const patientMsg = $json.patient_message.toLowerCase();

// Check 1: medical compliance blocked patterns
const blockedPatterns = [/\b(diagnose|diagnosed|diagnosis)\b/i, /\b(prescribe|prescribed|prescription)\b/i, /\bI recommend (you take|the medication)\b/i, /\b(treatment plan|medical advice)\b/i];
for (const pattern of blockedPatterns) {
  if (pattern.test(response)) {
    response = "I'm sorry, I had trouble processing that. Could you please rephrase your question? Our team is here to help you book an appointment.";
    break;
  }
}

// Check 2: emergency keywords in patient message
const emergencyKw = ['chest pain', 'bleeding heavily', "can't breathe", 'unconscious', 'overdose', 'stroke', 'heart attack', 'emergency', 'seizure', 'allergic reaction'];
if (emergencyKw.some(kw => patientMsg.includes(kw))) {
  response = 'Please call emergency services (911 / 999 / 112) immediately. This is an appointment booking service only. Stay safe.';
}

// Check 3: empty response
if (!response || response.trim().length === 0) {
  response = "I'm sorry, I had trouble processing that. Could you please rephrase your question? Our team is here to help you book an appointment.";
}

// Check 4: truncate at 600 chars word boundary
if (response.length > 600) {
  response = response.substring(0, 600).replace(/\s+\S*$/, '') + '...';
}

return [{json: { ...$json, safe_message: response }}];

let safeMessage = $json.safe_message;
let hasBooking = false;
let bookingData = null;

const parts = $json.ai_raw_response.split('BOOKING_JSON:');
if (parts.length > 1) {
  try {
    const jsonStr = parts[1].trim();
    bookingData = JSON.parse(jsonStr);
    // Validate schema
    const emailRegex = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
    const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
    const timeRegex = /^\d{2}:\d{2}$/;
    if (bookingData.name && bookingData.name.length >= 2 &&
        emailRegex.test(bookingData.email) &&
        bookingData.service &&
        dateRegex.test(bookingData.date) &&
        timeRegex.test(bookingData.time)) {
      hasBooking = true;
      // Remove BOOKING_JSON line from safe_message
      safeMessage = safeMessage.split('BOOKING_JSON:')[0].trim();
    } else {
      bookingData = null;
    }
  } catch (e) {
    bookingData = null;
  }
}

return [{json: { ...$json, safe_message: safeMessage, has_booking: hasBooking, booking_data: bookingData }}];

const supabaseUrl = $env.SUPABASE_URL;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const clinicId = $json.clinic_id;
const bd = $json.booking_data;

// Upsert patient
const upsertRes = await fetch(`${supabaseUrl}/rest/v1/patients`, {
  method: 'POST',
  headers: { 'apikey': key, 'Authorization': `Bearer ${key}`, 'Content-Type': 'application/json', 'Prefer': 'resolution=merge-duplicates,return=representation' },
  body: JSON.stringify({ clinic_id: clinicId, phone: $json.patient_phone, name: bd.name, email: bd.email, status: 'active' })
});
const patient = (await upsertRes.json())[0];

// Insert appointment
const slotStart = `${bd.date}T${bd.time}:00`;
const apptRes = await fetch(`${supabaseUrl}/rest/v1/appointments`, {
  method: 'POST',
  headers: { 'apikey': key, 'Authorization': `Bearer ${key}`, 'Content-Type': 'application/json', 'Prefer': 'return=representation' },
  body: JSON.stringify({ clinic_id: clinicId, patient_id: patient.patient_id, service: bd.service, slot_start: slotStart, status: 'confirmed' })
});

if (apptRes.status === 409) {
  return [{json: { ...$json, booking_failed: true, safe_message: "I'm sorry, that slot was just taken! Could you choose another time? I can show you what's available." }}];
}

// Audit log
await fetch(`${supabaseUrl}/rest/v1/audit_log`, {
  method: 'POST',
  headers: { 'apikey': key, 'Authorization': `Bearer ${key}`, 'Content-Type': 'application/json' },
  body: JSON.stringify({ clinic_id: clinicId, event_type: 'appointment_booked', payload: bd })
});

return [{json: { ...$json, booking_failed: false, patient_id: patient.patient_id }}];

const supabaseUrl = $env.SUPABASE_URL;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;

// Store assistant message
await fetch(`${supabaseUrl}/rest/v1/conversations`, {
  method: 'POST',
  headers: { 'apikey': key, 'Authorization': `Bearer ${key}`, 'Content-Type': 'application/json' },
  body: JSON.stringify({ clinic_id: $json.clinic_id, patient_phone: $json.patient_phone, role: 'assistant', content: $json.safe_message })
});

// Audit log
await fetch(`${supabaseUrl}/rest/v1/audit_log`, {
  method: 'POST',
  headers: { 'apikey': key, 'Authorization': `Bearer ${key}`, 'Content-Type': 'application/json' },
  body: JSON.stringify({ clinic_id: $json.clinic_id, event_type: 'message_sent', payload: { provider_used: $json.provider_used, has_booking: $json.has_booking } })
});

return [{json: { success: true }}];

const supabaseUrl = $env.SUPABASE_URL;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;

// Insert into DLQ
await fetch(`${supabaseUrl}/rest/v1/dead_letter_queue`, {
  method: 'POST',
  headers: { 'apikey': key, 'Authorization': `Bearer ${key}`, 'Content-Type': 'application/json' },
  body: JSON.stringify({ clinic_id: $json.clinic_id, workflow_name: 'WF-2', payload: { patient_phone: $json.patient_phone, patient_message: $json.patient_message, message_id: $json.message_id }, error_message: 'All AI providers exhausted/down', status: 'pending', retry_count: 0, max_retries: 3 })
});

// Alert admin via Telegram
await fetch(`https://api.telegram.org/bot${$env.TELEGRAM_ADMIN_BOT_TOKEN}/sendMessage`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ chat_id: $env.TELEGRAM_ADMIN_CHAT_ID, text: `\u26a0 All AI providers down for clinic ${$json.clinic_id}. Message queued in DLQ.` })
});

return [{json: { ...$json, safe_message: "I'm sorry, I had trouble processing that. Could you please rephrase your question? Our team is here to help you book an appointment." }}];
